import datetime
import hashlib
import json
import os
import re
import sys

FIXED_NOW = '2026-09-19T00:00:00Z'
EXPECTED_CANDIDATES = {
    'TASK-42-ALPHA': 'rev-7',
    'TASK-42-BETA': 'rev-8',
}
REQUIRED_SCOPE = {
    'read_local_artifact',
    'compute_sha256',
    'report_validation',
}
ALLOWED_SCOPE = set(REQUIRED_SCOPE)
BASE = os.path.realpath(os.path.dirname(os.path.abspath(__file__)))
TASK_RE = re.compile(r'^TASK-[A-Z0-9]+(?:-[A-Z0-9]+)*$')
REV_RE = re.compile(r'^rev-[1-9][0-9]*$')
OWNER_RE = re.compile(r'^[a-z][a-z0-9-]{1,63}$')
REF_RE = re.compile(r'^[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$')


class ValidationError(ValueError):
    pass


def reject_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValidationError('duplicate JSON key: ' + key)
        result[key] = value
    return result


def load_packet(path):
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            return json.load(handle, object_pairs_hook=reject_duplicates)
    except json.JSONDecodeError as error:
        raise ValidationError('malformed JSON: ' + error.msg)


def confined_file(root, name):
    if not isinstance(name, str) or not name or os.path.isabs(name):
        raise ValidationError('file path must be a nonempty relative string')
    canonical_root = os.path.realpath(root)
    canonical_path = os.path.realpath(os.path.join(canonical_root, name))
    try:
        inside = os.path.commonpath([canonical_root, canonical_path]) == canonical_root
    except ValueError:
        inside = False
    if not inside:
        raise ValidationError('file path escapes exercise directory')
    return canonical_path


def required_string(obj, name):
    value = obj.get(name)
    if not isinstance(value, str) or not value:
        raise ValidationError(name + ' must be a nonempty string')
    return value


def utc_datetime(value, field):
    if not isinstance(value, str):
        raise ValidationError(field + ' must be a string')
    if not (value.endswith('Z') or value.endswith('+00:00')):
        raise ValidationError(field + ' must include an explicit UTC offset')
    normalized = value[:-1] + '+00:00' if value.endswith('Z') else value
    try:
        parsed = datetime.datetime.fromisoformat(normalized)
    except ValueError:
        raise ValidationError(field + ' must be ISO-8601')
    if parsed.tzinfo is None or parsed.utcoffset() != datetime.timedelta(0):
        raise ValidationError(field + ' must use UTC')
    return parsed


def validate_packet(packet, artifact_argument, root=BASE, now_text=FIXED_NOW, expected_candidates=None):
    expected_candidates = EXPECTED_CANDIDATES if expected_candidates is None else expected_candidates
    if not isinstance(packet, dict):
        raise ValidationError('packet must be an object')
    required = (
        'task_id', 'candidate_revision', 'sender_owner', 'receiver_owner',
        'artifact', 'scope', 'evidence', 'expires_at', 'side_effect_status',
        'authenticity', 'human_approved', 'recovery', 'intended_next_step'
    )
    for key in required:
        if key not in packet:
            raise ValidationError('missing ' + key)

    task = required_string(packet, 'task_id')
    revision = required_string(packet, 'candidate_revision')
    if TASK_RE.fullmatch(task) is None:
        raise ValidationError('task_id has invalid shape')
    if REV_RE.fullmatch(revision) is None:
        raise ValidationError('candidate_revision has invalid shape')
    if task not in expected_candidates:
        raise ValidationError('unexpected task_id')
    if revision != expected_candidates[task]:
        raise ValidationError('stale or unexpected candidate_revision')

    for owner_field in ('sender_owner', 'receiver_owner'):
        owner = required_string(packet, owner_field)
        if OWNER_RE.fullmatch(owner) is None:
            raise ValidationError(owner_field + ' has invalid shape')

    artifact = packet['artifact']
    if not isinstance(artifact, dict):
        raise ValidationError('artifact must be an object')
    artifact_ref = required_string(artifact, 'ref')
    if REF_RE.fullmatch(artifact_ref) is None:
        raise ValidationError('artifact ref has invalid shape')
    expected_digest = required_string(artifact, 'sha256')
    if len(expected_digest) != 64 or any(c not in '0123456789abcdef' for c in expected_digest):
        raise ValidationError('artifact sha256 must be 64 lowercase hex characters')

    scope = packet['scope']
    if not isinstance(scope, list) or any(not isinstance(item, str) for item in scope):
        raise ValidationError('scope must be a list of strings')
    if len(scope) != len(set(scope)):
        raise ValidationError('scope must not contain duplicates')
    scope_set = set(scope)
    if not scope_set.issubset(ALLOWED_SCOPE):
        raise ValidationError('unsafe scope escalation')
    if scope_set != REQUIRED_SCOPE:
        raise ValidationError('required scope is missing')

    evidence = packet['evidence']
    if not isinstance(evidence, list) or any(not isinstance(item, dict) for item in evidence):
        raise ValidationError('evidence must be a list of objects')
    refs = []
    for item in evidence:
        item_ref = item.get('ref')
        if not isinstance(item_ref, str) or not item_ref or REF_RE.fullmatch(item_ref) is None:
            raise ValidationError('evidence ref must be a valid nonempty string')
        if not isinstance(item.get('kind'), str) or not item.get('kind'):
            raise ValidationError('evidence kind must be a nonempty string')
        if not isinstance(item.get('result'), str) or not item.get('result'):
            raise ValidationError('evidence result must be a nonempty string')
        refs.append(item_ref)
    if len(refs) != len(set(refs)):
        raise ValidationError('duplicate evidence')
    if artifact_ref not in refs:
        raise ValidationError('artifact evidence is absent')
    result_items = [item for item in evidence if item['ref'] == 'result-1']
    if len(result_items) != 1:
        raise ValidationError('required result evidence is absent or duplicated')
    if result_items[0]['result'] != 'PASS_FOR_CONSUMER_VALIDATION':
        raise ValidationError('required result is not present')

    if not isinstance(packet['authenticity'], bool):
        raise ValidationError('authenticity must be Boolean')
    if not isinstance(packet['human_approved'], bool):
        raise ValidationError('human_approved must be Boolean')
    if not isinstance(packet['recovery'], str) or not packet['recovery']:
        raise ValidationError('recovery must be a nonempty string')
    if not isinstance(packet['intended_next_step'], str) or not packet['intended_next_step']:
        raise ValidationError('intended_next_step must be a nonempty string')

    status = packet['side_effect_status']
    if not isinstance(status, str) or status not in ('NONE_PENDING', 'UNKNOWN'):
        raise ValidationError('invalid side_effect_status')
    if status == 'UNKNOWN':
        raise ValidationError('external side-effect state is UNKNOWN; stop and reconcile')

    expires = utc_datetime(packet['expires_at'], 'expires_at')
    now = utc_datetime(now_text, 'fixed time')
    if expires <= now:
        raise ValidationError('evidence expired')

    packet_artifact_path = confined_file(root, artifact_ref)
    supplied_artifact_path = confined_file(root, artifact_argument)
    if packet_artifact_path != supplied_artifact_path:
        raise ValidationError('artifact argument does not match packet artifact ref')
    try:
        with open(supplied_artifact_path, 'rb') as handle:
            digest = hashlib.sha256(handle.read()).hexdigest()
    except OSError as error:
        raise ValidationError('cannot read artifact: ' + str(error))
    if digest != expected_digest:
        raise ValidationError('changed artifact: local digest does not match packet')

    return ('PASS task_id=' + task + ' revision=' + revision +
            ' local_digest=' + digest +
            ' authenticity=UNKNOWN human_approval=UNKNOWN side_effects=' + status)


def run(argv):
    if len(argv) != 3:
        print('REJECT usage: validator.py PACKET.json ARTIFACT')
        return 1
    try:
        packet_path = confined_file(BASE, argv[1])
        packet = load_packet(packet_path)
        print(validate_packet(packet, argv[2], BASE))
        return 0
    except (OSError, ValidationError) as error:
        print('REJECT ' + str(error))
        return 1


if __name__ == '__main__':
    sys.exit(run(sys.argv))

